"""Build a standalone resource-negotiation research report from measured data."""
from __future__ import annotations

import json
from pathlib import Path

from docx import Document
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Cm, Pt, RGBColor

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "deliverables/ResearchRadar_MAS_Resource_Negotiation.docx"
RESULTS = ROOT / "experiments/lab3/results"
summary = json.loads((RESULTS / "summary.json").read_text(encoding="utf-8"))
paired = json.loads((RESULTS / "paired.json").read_text(encoding="utf-8"))
metadata = json.loads((RESULTS / "metadata.json").read_text(encoding="utf-8"))
lookup = {(x["scenario"], x["mode"]): x for x in summary}
delta = {x["scenario"]: x for x in paired}

doc = Document()
sec = doc.sections[0]
sec.page_width, sec.page_height = Cm(21), Cm(29.7)
sec.top_margin, sec.bottom_margin = Cm(2), Cm(1.9)
sec.left_margin, sec.right_margin = Cm(2.4), Cm(2.2)
normal = doc.styles["Normal"]
normal.font.name, normal.font.size = "Times New Roman", Pt(11)
normal.paragraph_format.space_after = Pt(6)
normal.paragraph_format.line_spacing = 1.12
for name, size in (("Title", 17), ("Heading 1", 14), ("Heading 2", 12)):
    style = doc.styles[name]
    style.base_style = normal
    style.font.name = "Times New Roman"
    style.font.size = Pt(size)
    style.font.bold = True
    style.font.color.rgb = RGBColor(0, 0, 0)
    style.paragraph_format.space_before = Pt(12)
    style.paragraph_format.space_after = Pt(6)
    style.paragraph_format.keep_with_next = True
title_properties = doc.styles["Title"]._element.pPr
for border in title_properties.findall(qn("w:pBdr")):
    title_properties.remove(border)


def para(text: str, style: str | None = None):
    return doc.add_paragraph(text, style)


def heading(text: str):
    doc.add_heading(text, 1)


def table(headers: list[str], rows: list[tuple[str, ...]]):
    obj = doc.add_table(rows=1, cols=len(headers))
    obj.style = "Table Grid"
    obj.alignment = WD_TABLE_ALIGNMENT.CENTER
    for cell, value in zip(obj.rows[0].cells, headers):
        cell.text = value
    for values in rows:
        for cell, value in zip(obj.add_row().cells, values):
            cell.text = str(value)
    for row in obj.rows:
        row._tr.get_or_add_trPr().append(OxmlElement("w:cantSplit"))
        for cell in row.cells:
            for paragraph in cell.paragraphs:
                for run in paragraph.runs:
                    run.font.size = Pt(8.5)


def figure(anchor: str, caption: str):
    mark = para(anchor)
    mark.alignment = WD_ALIGN_PARAGRAPH.CENTER
    mark.paragraph_format.keep_with_next = True
    cap = para(caption)
    cap.alignment = WD_ALIGN_PARAGRAPH.CENTER
    cap.paragraph_format.space_after = Pt(10)


title = para("Переговоры и разрешение ресурсных конфликтов в многоагентной исследовательской системе ResearchRadar MAS", "Title")
title.alignment = WD_ALIGN_PARAGRAPH.CENTER
para("")
for line in ("Коротаев Андрей Дмитриевич", "Группа Б24-507", "2026"):
    paragraph = para(line)
    paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
doc.add_page_break()

heading("Аннотация")
para("Рассматривается конфликт между автономными участниками научно-информационного поиска за ограниченный бюджет углублённых проверок. После получения публикаций и новостей научный, новостной и сопоставляющий агенты формируют несовместимые заявки. Сравниваются прозрачная последовательная политика и двухраундовые переговоры с уступками, подтверждением соглашения и ограниченным арбитражем. Бюджет связан с выполняемыми операциями над метаданными, аннотациями и заголовками. На фиксированных синтетических материалах проведены пять сценариев по 12 парных повторов, всего 120 запусков. При умеренном дефиците переговоры повысили оценочную полезность и выровняли доли удовлетворения заявок; при неравной ценности возник компромисс между справедливостью и полезностью. Измерены сообщения, время и нарушения ресурсных ограничений. Содержательные выводы о научной истинности не выводятся из тематической близости материалов.")

heading("1. Постановка задачи")
para("Поисковый контур ResearchRadar MAS уже распределяет задания между исполнителями. После поиска появляется иная задача: несколько участников хотят углублённо проверить собственные материалы, но общий ресурс ограничен. Научный агент предпочитает проверить библиографию и доступную аннотацию, новостной — происхождение заголовка, агент сопоставления — потенциальную тематическую связь. Их локальные интересы конкурируют за одни и те же кредиты. Исследовательский вопрос состоит в том, как явное согласование частичных проверок меняет оценочную полезность, нормированную удовлетворённость, коммуникационные затраты и соблюдение ограничений по сравнению с корректной простой политикой.")
para("Гипотезы сформулированы до анализа данных: при достаточном бюджете оба режима дадут одинаковую проверенную работу, но переговоры добавят сообщения; при дефиците уступки могут увеличить число обслуженных заявок и удовлетворённость, хотя не обязаны повышать сумму полезностей при любой структуре ценностей; отсутствие ответа участника увеличит длительность и может потребовать арбитража.")

heading("2. Модель интересов и ограниченного ресурса")
para("Заявка i задаётся участником, операцией, материалами, полной потребностью d_i = 2 кредита, допустимым минимумом m_i = 1, публичным приоритетом p_i и частными оценками v_i(2) и v_i(1). Нулевая выдача имеет полезность 0. Участник принимает только предложение, чья оценка не ниже его порога резервирования. Бюджет B — общий лимит оплачиваемых проверок. Для любого состояния выполняются spent + held ≤ B и active ≤ concurrent_slots. Кредит, потраченный на начатую проверку, не возвращается; при её завершении освобождается только одновременный слот. Отмена до запуска возвращает резерв. ID соглашения связывает выделение с одной заявкой и её владельцем.")
para("Эффективность измеряется суммой модельных оценок фактически выполненных проверок, а не истинностью утверждений: U = Σ_i v_i(x_i). Справедливость измеряется индексом Джейна для нормированных долей s_i = x_i / d_i: J = (Σ_i s_i)² / (n Σ_i s_i²). При нулевом выделении J принимается равным нулю. Равное число кредитов само по себе не трактуется как универсальная справедливость при разных ценностях; U и J представлены отдельно.")

heading("3. Архитектура и исполнение проверок")
para("Текущие централизованное назначение и Contract Net выбирают исполнителей исходных поисковых задач. Новый ресурсный контур включается после сбора материалов и не изменяет их протоколы. Научная заявка проверяет идентификаторы, авторов и, при полной выдаче, доступную аннотацию. Новостная проверка фиксирует источник и дату, но без текста статьи оставляет утверждение непроверенным. Проверка связи сопоставляет доступные заголовки и, при полной выдаче, аннотацию; пересечение терминов обозначается лишь тематическим кандидатом. Каждое заключение содержит идентификаторы и область доступных данных.")
figure("FIGURE_ARCH", "Рисунок 1 — Поиск, согласование ресурса и исполнение проверок")
para("Ресурсный журнал атомарно резервирует кредиты под ID соглашения, разрешает начало лишь владельцу соответствующей заявки, учитывает расход, освобождает слот и отвергает повторный расход. Участник без подтверждённого ресурса не запускает защищённую операцию. При таймауте до начала резерв возвращается; после старта расход фиксируется, а слот освобождается.")

heading("4. Протокол переговоров и контрольный режим")
para("Контрольная политика обслуживает заявки в порядке их появления: выдаёт полные два кредита, если они доступны, иначе один кредит на допустимую частичную проверку. Она соблюдает те же жёсткие ограничения, что и переговоры. Переговорный посредник в первом раунде предлагает полные проверки в порядке публичного приоритета. Агенты отвечают самостоятельно: принимают приемлемый объём, предлагают частичную проверку вместо отказа или уступают один кредит при достаточной собственной частичной ценности и наличии неудовлетворённых коллег. Посредник перераспределяет освободившиеся кредиты по раскрытым оценкам и во втором раунде требует принятия конкретных условий. Молчание ограничивает ожидание и запускает арбитражную базовую политику среди ответивших; отказ означает отсутствие договора. Арбитраж не заменяет обычные раунды.")
figure("FIGURE_PROTOCOL", "Рисунок 2 — Обмен сообщениями и фиксация соглашения")
para("Сообщения имеют уникальные ID, адрес, тип, ID исследования и correlation_id. Проверяются полномочия отправителя, получатель, раунд и связь ответа с отправленным предложением. Конечный результат принимается лишь от владельца договора и в ответ на его commit. Два раунда, сроки ожидания и явное завершение исключают бесконечный торг. Трасса сохраняет предложение, уступку, решение и исполнение.")

heading("5. Экспериментальная методика")
para(f"Для сравнения использован один замороженный синтетический поисковый результат с научными и новостными материалами. Режимы получают одинаковые заявки, локальные оценки, бюджет, модель задержки и seed в каждой паре. Проведено пять сценариев: достаточные ресурсы, умеренный дефицит, сильный дефицит, неравные ценности частичных проверок и молчание одного участника. В каждом сценарии 12 пар, всего {metadata['runs']} отдельных запусков. Случайные изменения предварительных оценок ограничены ±3% и одинаковы внутри пары. Сеть и платная модель в эксперименте не вызываются. Скрипт фиксирует входы, исходные измерения, сводки, парные разности, трассы и контрольные суммы данных.")
para("Зависимые показатели: выполненные проверки, оценочная полезность, J, расход кредитов, число сообщений и контрпредложений, обращения к арбитражу, длительность переговоров и полное wall-clock время. Сообщения подсчитываются из фактически переданной трассы. В каждом запуске автоматически проверяются переполнение бюджета и лимита активных слотов. Времена измерены perf_counter и зависят от планировщика ОС; сумму длительностей отдельных проверок нельзя считать неперекрывающейся частью общего времени. Средние и стандартные отклонения рассчитываются по сохранённым строкам; парные разности используют одинаковый seed.")

doc.add_page_break()
heading("6. Результаты")
labels = {"sufficient": "Достаточно", "moderate_shortage": "Умеренный дефицит",
          "strong_shortage": "Сильный дефицит", "unequal_values": "Неравные ценности",
          "unresponsive_agent": "Молчание агента"}
table(["Сценарий", "Режим", "Полезность", "J", "Сообщения"], [
    (labels[scenario], "Контроль" if mode == "baseline" else "Переговоры",
     f"{lookup[(scenario, mode)]['estimated_utility_mean']:.2f}",
     f"{lookup[(scenario, mode)]['jain_normalized_satisfaction_mean']:.3f}",
     f"{lookup[(scenario, mode)]['messages_mean']:.1f}")
    for scenario in labels for mode in ("baseline", "negotiation")])
para("Таблица 1 — Средние значения по 12 повторам для каждого сценария; полезность выражена в условных единицах, J относится к нормированным долям индивидуальной полной потребности.")
figure("FIGURE_UTILITY", "Рисунок 3 — Средняя оценочная полезность выполненных проверок")
figure("FIGURE_FAIRNESS", "Рисунок 4 — Индекс Джейна по нормированной удовлетворённости")
figure("FIGURE_MESSAGES", "Рисунок 5 — Коммуникационная стоимость протокола")
figure("FIGURE_WALL", "Рисунок 6 — Полное время проверки в модельных сценариях")

heading("7. Интерпретация")
para(f"При достаточном бюджете режимы достигли одинаковой средней полезности {lookup[('sufficient','baseline')]['estimated_utility_mean']:.2f} и J = 1, но переговоры потребовали {lookup[('sufficient','negotiation')]['messages_mean']:.0f} сообщений вместо {lookup[('sufficient','baseline')]['messages_mean']:.0f}. Это цена согласования при отсутствии дефицита. При умеренном дефиците средняя парная прибавка полезности составила {delta['moderate_shortage']['estimated_utility_difference_mean']:+.2f}, а J вырос с {lookup[('moderate_shortage','baseline')]['jain_normalized_satisfaction_mean']:.2f} до {lookup[('moderate_shortage','negotiation')]['jain_normalized_satisfaction_mean']:.2f}. Переговоры заменили распределение 2/1/0 на три частичные проверки по одному кредиту.")
para(f"При сильном дефиците прирост полезности равен {delta['strong_shortage']['estimated_utility_difference_mean']:+.2f}, J вырос с {lookup[('strong_shortage','baseline')]['jain_normalized_satisfaction_mean']:.2f} до {lookup[('strong_shortage','negotiation')]['jain_normalized_satisfaction_mean']:.2f}. При неравных ценностях компромисс иной: средняя парная разность полезности {delta['unequal_values']['estimated_utility_difference_mean']:+.2f}, тогда как J увеличился на {delta['unequal_values']['jain_normalized_satisfaction_difference_mean']:+.2f}. Значит, более ровное обслуживание здесь оплачено потерей модельной суммарной ценности; скрывать этот конфликт одним сводным показателем нельзя.")
para(f"В сценарии молчания участника полезность и J совпали с контрольной политикой, но переговорный режим обратился к арбитражу {lookup[('unresponsive_agent','negotiation')]['arbitrations_mean']:.0f} раз за запуск и увеличил среднее wall-clock время с {lookup[('unresponsive_agent','baseline')]['wall_ms_mean']:.1f} до {lookup[('unresponsive_agent','negotiation')]['wall_ms_mean']:.1f} мс. Во всех {metadata['runs']} прогонах не отмечено превышения бюджета или лимита активных слотов. Нулевые нарушения отражают проверенную модель, а не гарантию безошибочности для произвольного внешнего окружения.")

heading("8. Доказательность и ограничения")
para("В отдельной LIVE-проверке с сохранённым ранее ответом Qwen поисковый контур завершил пять задач из пяти и получил материалы OpenAlex, Crossref, arXiv и Google News RSS без ошибок. Ресурсный контур выполнил три частичные проверки при бюджете три кредита. Научная проверка ограничилась метаданными, новость осталась непроверенным утверждением, а тематическое пересечение маркировано как кандидат. Повторного платного вызова Qwen для этой проверки не было; её сохранённая альтернативная формулировка использовалась только при планировании поиска.")
para("Значения полезности — предварительные оценки участников, а не известная истинная польза материалов. Синтетические заголовки и аннотации используются только для контролируемого сравнения протоколов. Проверка научного идентификатора подтверждает наличие поля в полученной записи, но не истинность результатов статьи. Тематическое пересечение не доказывает, что новость ссылается на статью. Новостное утверждение остаётся непроверенным при отсутствии полного текста и независимого первоисточника. В LIVE-режиме внешние API могут отказать или вернуть неполные метаданные; система сохраняет частичные результаты.")
para("Модель содержит одну заявку от каждой из трёх проверяющих ролей, целочисленный ресурс и два раунда. Она не исследует стратегическое сокрытие ценностей, коалиции и качество полной статьи. Индекс Джейна измеряет равномерность долей потребности, а не этическую справедливость всех решений. Численные миллисекунды зависят от Windows и не переносятся на сетевую эксплуатацию. Ограниченный бюджет проверок не является денежным балансом OpenRouter. Qwen может сформировать альтернативный запрос до поиска через отдельный бюджетируемый клиент; в массовых испытаниях она не вызывалась, чтобы обе политики получили одинаковые входные сведения.")

heading("Заключение")
para("Ресурсный конфликт разрешается самостоятельным сообщенческим протоколом, отдельным от назначения поисковых исполнителей. Переговоры дают проверяемые уступки, соглашения и атомарные выделения, а принятые проверки действительно выполняются. При дефиците и близких частичных ценностях они обслуживают больше заявок и улучшают нормированную удовлетворённость; при неравных ценностях та же уступка снижает суммарную оценочную полезность. При достаточном бюджете и молчании агента дополнительные сообщения не дают выигрыша. Поэтому выбор режима должен учитывать дефицит, структуру оценок и цену ожидания.")
para("Воспроизведение: tools/run_negotiation_experiments.py; первичные данные и входы — experiments/lab3/results/raw.csv и inputs.json; агрегаты — summary.json и paired.json; условия — metadata.json и experiments/lab3/scenarios.json; трассы — traces/. Исходники протокола — src/researchradar/negotiation.py и resources.py. Стенд не требует Git при запуске из архивной копии.")

OUT.parent.mkdir(exist_ok=True)
doc.save(OUT)
print(OUT)
